package app.quietagent.workspace;

import android.app.*; import android.content.*; import android.os.*; import java.nio.charset.StandardCharsets; import java.io.*; import java.security.*; import java.util.*; import java.util.concurrent.atomic.AtomicBoolean; import org.json.*;

public final class UnifiedAgentService extends Service {
  public static final String ACTION_RUN="app.quietagent.workspace.UNIFIED_RUN",ACTION_CANCEL="app.quietagent.workspace.UNIFIED_CANCEL",EXTRA_JOB="jobId";
  private static final String SMS_PENDING="private:pending-sms-table.csv";
  private static final Object LOCK=new Object(); private static String active; private static final AtomicBoolean cancel=new AtomicBoolean();

  public static String start(Context c,String request){if(request==null||request.trim().length()<2)throw new IllegalArgumentException("任务不能为空");String id="unified-"+UUID.randomUUID();write(c,id,obj("jobId",id,"request",request.trim(),"state","QUEUED","createdAt",System.currentTimeMillis()));Intent i=new Intent(c,UnifiedAgentService.class).setAction(ACTION_RUN).putExtra(EXTRA_JOB,id);if(Build.VERSION.SDK_INT>=26)c.startForegroundService(i);else c.startService(i);return id;}
  public static void cancel(Context c,String id){c.startService(new Intent(c,UnifiedAgentService.class).setAction(ACTION_CANCEL).putExtra(EXTRA_JOB,id));}
  public static JSONObject status(Context c,String id)throws IOException{return read(c,id);}
  public static JSONArray history(Context c)throws IOException{File d=dir(c);JSONArray a=new JSONArray();File[] fs=d.listFiles();if(fs!=null)for(File f:fs)if(f.getName().endsWith(".json"))try{a.put(new JSONObject(readFile(f)));}catch(Exception e){throw new IOException("历史记录损坏",e);}return a;}

  @Override public void onCreate(){super.onCreate();if(Build.VERSION.SDK_INT>=26){NotificationChannel n=new NotificationChannel("quiet-unified","Quiet Agent",NotificationManager.IMPORTANCE_LOW);n.setSound(null,null);n.enableVibration(false);getSystemService(NotificationManager.class).createNotificationChannel(n);}recover();}
  private void recover(){File[] fs=dir(this).listFiles();if(fs==null)return;for(File f:fs)try{JSONObject j=new JSONObject(readFile(f));if("RUNNING".equals(j.optString("state"))){j.put("state","INTERRUPTED").put("failure","服务中断，需要重新开始");write(this,j.getString("jobId"),j);}}catch(Exception ignored){}}
  @Override public int onStartCommand(Intent i,int flags,int sid){if(i!=null&&ACTION_CANCEL.equals(i.getAction())){synchronized(LOCK){if(Objects.equals(active,i.getStringExtra(EXTRA_JOB)))cancel.set(true);}return START_NOT_STICKY;}if(i==null||!ACTION_RUN.equals(i.getAction()))return START_NOT_STICKY;String id=i.getStringExtra(EXTRA_JOB);synchronized(LOCK){if(active!=null)return START_NOT_STICKY;active=id;cancel.set(false);}if(Build.VERSION.SDK_INT>=26)startForeground(78,new Notification.Builder(this,"quiet-unified").setSmallIcon(android.R.drawable.ic_menu_manage).setContentTitle("Quiet Agent").setContentText("后台处理中").setOnlyAlertOnce(true).setOngoing(true).build());new Thread(()->run(id),"unified-agent").start();return START_NOT_STICKY;}

  private void run(String id){boolean claimed=false,changed=false;int successes=0,errors=0;long end=System.currentTimeMillis()+600000;try{JSONObject j=read(this,id);if(!"QUEUED".equals(j.optString("state")))throw new IOException("任务不是QUEUED，拒绝重放");update(this,id,"RUNNING",null);claimed=true;WorkspaceStore s=new WorkspaceStore(this);ToolExecutor e=new ToolExecutor(s,this);JSONObject meta=e.metadata().put("roots",new JSONArray(s.listRoots()));String request=j.optString("request");boolean smsTask=isSmsTask(request);SmsTableBuffer smsTable=smsTask?new SmsTableBuffer(id,j.optLong("createdAt",System.currentTimeMillis())):null;StringBuilder tr=new StringBuilder("request=").append(request).append("\nmetadata=").append(meta);if(smsTask)tr.append("\nhost_rule=短信行可以分批提交，但宿主只会在finish时生成一个汇总CSV");for(int n=1;n<=80;n++){checkDeadline(end);update(this,id,"RUNNING","第 "+n+" 次 · 正在决定下一步");appendEvent(this,id,n,"planning","正在决定下一步","");JSONObject raw=app.quietagent.LlmIntentRouter.unifiedTurn(this,tr.toString(),meta);checkDeadline(end);tr.append("\nmodel=").append(limit(raw.toString(),12000));JSONObject q=ToolCallEnvelope.normalize(raw);String tool=q.getString("tool");JSONObject args=q.getJSONObject("args");update(this,id,"RUNNING","第 "+n+" 次 · "+toolLabel(tool));appendEvent(this,id,n,"running",toolLabel(tool),"");if("finish".equals(tool)){String summary=args.optString("summary","");if(successes<1||summary.trim().isEmpty()||summary.length()>4000){errors++;tr.append("\ntool_error=finish requires successful work and summary");audit(id,tool,obj("error","premature finish"),n);appendEvent(this,id,n,"failed",toolLabel(tool),"尚未具备完成条件");continue;}JSONArray resultIds=args.optJSONArray("resultIds");if(resultIds==null)resultIds=new JSONArray();if(smsTable!=null&&smsTable.hasRows()){JSONObject committed=e.execute("write_table",smsTable.toArgs());String actual=committed.getString("id");resultIds=replacePending(resultIds,actual);changed=true;audit(id,"write_table_commit",obj("id",actual,"rows",smsTable.rowCount()),n);}for(int ri=0;ri<resultIds.length();ri++)s.resolve(resultIds.getString(ri));checkDeadline(end);appendEvent(this,id,n,"success",toolLabel(tool),"任务已完成");j=read(this,id);j.put("summary",summary).put("resultIds",resultIds).put("errors",errors).put("state",errors>0?"PARTIAL":"COMPLETED").put("phase","完成").put("updatedAt",System.currentTimeMillis());write(this,id,j);notifyDone(id);return;}audit(id,tool,obj("stage","prepare"),n);try{JSONObject r;if(smsTable!=null&&"write_table".equals(tool)){smsTable.add(args);r=obj("id",SMS_PENDING,"bufferedRows",smsTable.rowCount(),"willCreateOneCsvAtFinish",true);}else{r=e.execute(tool,args);changed|=isWrite(tool);}successes++;tr.append("\nresult=").append(limit(r.toString(),24000));audit(id,tool,r,n);appendEvent(this,id,n,"success",toolLabel(tool),toolDetail(tool,args,r));}catch(Exception x){errors++;tr.append("\ntool_error=").append(x.getMessage());audit(id,tool,obj("error",x.getMessage()),n);appendEvent(this,id,n,"failed",toolLabel(tool),safeDetail(tool,x.getMessage()));}}throw new IOException("超过工具调用限制");}catch(Exception x){if(claimed)update(this,id,cancel.get()?"CANCELLED":changed?"PARTIAL":"FAILED",x.getMessage());}finally{synchronized(LOCK){active=null;}stopForeground(true);stopSelf();}}
  private void checkDeadline(long end)throws IOException{if(cancel.get())throw new IOException("任务已取消");if(System.currentTimeMillis()>end)throw new IOException("任务已超时");}
  private static boolean isSmsTask(String request){String q=request==null?"":request.toLowerCase(Locale.ROOT);return q.contains("短信")||q.contains("sms");}
  private static JSONArray replacePending(JSONArray requested,String actual)throws JSONException{JSONArray out=new JSONArray();boolean added=false;for(int i=0;i<requested.length();i++){String id=requested.optString(i);if(SMS_PENDING.equals(id)){if(!added){out.put(actual);added=true;}}else if(!id.isEmpty())out.put(id);}if(!added)out.put(actual);return out;}
  static final class SmsTableBuffer {private JSONArray headers,rows=new JSONArray();private final String name;SmsTableBuffer(String job,long created){String suffix=job.substring(Math.max(0,job.length()-6));name="短信整理-"+new java.text.SimpleDateFormat("yyyyMMdd-HHmm",Locale.ROOT).format(new Date(created))+"-"+suffix+".csv";}void add(JSONObject a)throws Exception{if(!WorkspaceStore.PRIVATE_ROOT.equals(a.optString("rootId")))throw new IOException("短信汇总表只能生成在成果区");JSONArray h=a.getJSONArray("headers"),r=a.getJSONArray("rows");if(h.length()<1||h.length()>24)throw new IOException("短信表头无效");if(headers==null)headers=new JSONArray(h.toString());else if(!headers.toString().equals(h.toString()))throw new IOException("短信分批表头必须一致");for(int i=0;i<r.length();i++){JSONArray row=r.getJSONArray(i);if(row.length()!=headers.length())throw new IOException("短信表格列数不一致");rows.put(new JSONArray(row.toString()));if(rows.length()>500)throw new IOException("短信表格超过500行");}}boolean hasRows(){return headers!=null&&rows.length()>0;}int rowCount(){return rows.length();}JSONObject toArgs()throws JSONException{return new JSONObject().put("rootId",WorkspaceStore.PRIVATE_ROOT).put("name",name).put("headers",headers).put("rows",rows);}}

  private static synchronized void appendEvent(Context c,String id,int call,String status,String label,String detail)throws IOException{try{JSONObject job=read(c,id);JSONArray old=job.optJSONArray("events"),events=new JSONArray();if(old!=null)for(int i=0;i<old.length();i++){JSONObject e=old.optJSONObject(i);if(e!=null&&e.optInt("call")!=call)events.put(e);}events.put(new JSONObject().put("call",call).put("status",status).put("label",label).put("detail",detail==null?"":detail).put("at",System.currentTimeMillis()));while(events.length()>12)events.remove(0);job.put("events",events).put("updatedAt",System.currentTimeMillis());write(c,id,job);}catch(JSONException e){throw new IOException("无法记录执行进度",e);}}
  private static String toolLabel(String tool){if("list".equals(tool))return"查看工作区资料";if("stat".equals(tool))return"核对文件信息";if("find".equals(tool))return"查找文件";if("read_document".equals(tool))return"读取文档";if("read_documents".equals(tool))return"批量读取文档";if("search".equals(tool))return"搜索已读内容";if("ocr".equals(tool))return"识别图片文字";if("receipt".equals(tool))return"识别一张票据";if("receipt_batch".equals(tool))return"批量识别票据";if("hash".equals(tool))return"校验文件内容";if("duplicates".equals(tool))return"查找重复文件";if("mkdir".equals(tool))return"创建文件夹";if("rename".equals(tool))return"重命名文件";if("copy".equals(tool))return"复制文件";if("move".equals(tool))return"移动文件";if("trash".equals(tool))return"移入回收区";if("write_text".equals(tool))return"更新文本";if("write_table".equals(tool))return"生成表格";if("report".equals(tool))return"生成报告";if("zip".equals(tool))return"生成归档";if("finish".equals(tool))return"完成任务";return"处理资料";}
  private static String toolDetail(String tool,JSONObject args,JSONObject result){if("list".equals(tool))return"已列出 "+length(result.optJSONArray("items"))+" 项";if("read_documents".equals(tool))return"已读取 "+result.optInt("count")+" 份";if("receipt_batch".equals(tool))return"已识别 "+result.optInt("count")+" 张";if("read_document".equals(tool))return"已读取 1 份";if("ocr".equals(tool)||"receipt".equals(tool))return"已识别 1 张";if("write_table".equals(tool))return"已整理 "+length(args.optJSONArray("rows"))+" 行";return"已完成";}
  private static int length(JSONArray a){return a==null?0:a.length();}
  private static String safeDetail(String tool,String ignored){if("list".equals(tool)||"stat".equals(tool))return"无法访问该工作区项目，请检查授权";if("ocr".equals(tool)||"receipt".equals(tool)||"receipt_batch".equals(tool))return"图片无法识别或授权已失效";return"执行失败，已记录原因";}

  private void notifyDone(String id){Intent i=new Intent(this,WorkspaceActivity.class).putExtra("jobId",id);PendingIntent p=PendingIntent.getActivity(this,79,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);getSystemService(NotificationManager.class).notify(79,new Notification.Builder(this,"quiet-unified").setSmallIcon(android.R.drawable.ic_menu_info_details).setContentTitle("Quiet Agent").setContentText("任务已完成").setContentIntent(p).setOnlyAlertOnce(true).build());}
  private static boolean isWrite(String t){return Arrays.asList("mkdir","rename","copy","move","trash","write_text","write_table","report","zip").contains(t);}
  private void audit(String id,String t,JSONObject r,int n)throws IOException{byte[] b=r.toString().getBytes(StandardCharsets.UTF_8);try{MessageDigest d=MessageDigest.getInstance("SHA-256");File f=new File(dir(this),id+".audit.jsonl");try(FileOutputStream o=new FileOutputStream(f,true)){o.write((obj("tool",t,"call",n,"resultSha256",hex(d.digest(b))).toString()+"\n").getBytes(StandardCharsets.UTF_8));o.getFD().sync();}}catch(GeneralSecurityException e){throw new IOException(e);}}
  private static File dir(Context c){File d=new File(c.getFilesDir(),"unified-jobs");if(!d.exists()&&!d.mkdirs())throw new IllegalStateException("无法创建任务目录");return d;}
  private static JSONObject read(Context c,String id)throws IOException{if(id==null||!id.matches("unified-[a-f0-9-]{36}"))throw new IOException("任务编号无效");File f=new File(dir(c),id+".json");if(!f.isFile())throw new IOException("任务不存在");try{return new JSONObject(readFile(f));}catch(Exception e){throw new IOException("任务记录损坏",e);}}
  private static void update(Context c,String id,String st,String fail){try{JSONObject j=read(c,id).put("state",st).put("phase",fail==null?st:fail).put("updatedAt",System.currentTimeMillis());if(fail!=null)j.put("failure",fail);write(c,id,j);}catch(Exception e){throw new IllegalStateException(e);}}
  private static void write(Context c,String id,JSONObject j){try{File f=new File(dir(c),id+".json.part"),t=new File(dir(c),id+".json");try(FileOutputStream o=new FileOutputStream(f)){o.write(j.toString().getBytes(StandardCharsets.UTF_8));o.getFD().sync();}if(!f.renameTo(t))throw new IOException("无法保存任务");}catch(Exception e){throw new IllegalStateException(e);}}
  private static String readFile(File f)throws IOException{return new String(java.nio.file.Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8);}
  private static String limit(String s,int n){return s.substring(0,Math.min(n,s.length()));}
  private static JSONObject obj(Object...v){JSONObject j=new JSONObject();try{for(int i=0;i<v.length;i+=2)j.put((String)v[i],v[i+1]);}catch(Exception e){throw new AssertionError(e);}return j;}
  private static String hex(byte[]b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(Locale.ROOT,"%02x",x&255));return s.toString();}
  @Override public IBinder onBind(Intent i){return null;}
}
